template<typename... Args>
auto sum(Args... args) {
    return (args + ...);           // unary right fold
}

template<typename... Args>
void print_all(const Args&... args) {
    ((std::cout << args << ' '), ...); // comma fold
    std::cout << '\n';
}

template<typename T, typename... Ts>
bool any_of(const T& value, const Ts&... options) {
    return ((value == options) || ...);
}

