#include <iostream>
#include <vector>

class Buffer {
    std::vector<int> data_{1, 2, 3};
public:
    // One function replaces the const and non-const overloads
    template<typename Self>
    auto&& at(this Self&& self, std::size_t i) {
        return std::forward<Self>(self).data_[i];
    }
};

int main() {
    Buffer b;
    b.at(0) = 42;
    const Buffer& cb = b;
    std::cout << cb.at(0) << '\n'; // 42

    // Recursive lambda: no std::function needed
    auto fib = [](this auto self, int n) -> int {
        return n < 2 ? n : self(n - 1) + self(n - 2);
    };
    std::cout << fib(10); // 55
}

