    void hello(const std::string& who) const {
        std::cout << name << " says hi to " << who << '\n';
    }
};

int add(int a, int b, int c) { return a + b + c; }

int main() {
    // std::invoke: free functions, lambdas and member functions alike
    Greeter g{"CppIndia"};
    std::invoke(&Greeter::hello, g, "Pune");
    std::cout << std::invoke(add, 1, 2, 3) << '\n';                  // 6

    // std::apply: tuple elements become the arguments
    auto args = std::make_tuple(10, 20, 30);
    std::cout << std::apply(add, args) << '\n';                       // 60

    auto print_all = [](const auto&... xs) { ((std::cout << xs << ' '), ...); };
    std::apply(print_all, std::tuple{"C++", 17, '!'});                // C++ 17 !
}

