#include <latch>
#include <barrier>
#include <thread>
#include <vector>
#include <iostream>
#include <syncstream>

int main() {
    constexpr int workers = 3;

    {   // latch: one-shot countdown
        std::latch ready(workers);
        std::vector<std::jthread> threads;
        for (int i = 0; i < workers; ++i)
            threads.emplace_back([&ready, i] {
                std::osyncstream(std::cout) << "worker " << i << " ready\n";
                ready.count_down();
            });
        ready.wait();
        std::cout << "all workers ready\n";
    }   // threads join here, before the latch goes away

    {   // barrier: reusable, runs a completion step after each phase
        int phase = 0;
        std::barrier sync(workers, [&phase]() noexcept {
            std::cout << "-- phase " << phase++ << " done --\n";
        });
        std::vector<std::jthread> threads;
        for (int i = 0; i < workers; ++i)
            threads.emplace_back([&sync] {
                for (int step = 0; step < 2; ++step) sync.arrive_and_wait();
            });
    }
}

