int main() {
    // Inspect a float's bits without undefined behaviour
    float f = 1.0f;
    auto bits = std::bit_cast<std::uint32_t>(f);
    std::cout << std::hex << "1.0f bits: 0x" << bits << std::dec << '\n'; // 0x3f800000

    std::uint32_t x = 0b1011'0000;
    std::cout << "popcount: "      << std::popcount(x)      << '\n'; // 3
    std::cout << "countr_zero: "   << std::countr_zero(x)   << '\n'; // 4
    std::cout << "bit_width: "     << std::bit_width(x)     << '\n'; // 8
    std::cout << "bit_ceil(100): " << std::bit_ceil(100u)   << '\n'; // 128
    std::cout << std::boolalpha << "has_single_bit(64): " << std::has_single_bit(64u) << '\n';

    static_assert(std::popcount(0xFFu) == 8); // all constexpr
}

