int main() {
    std::vector<std::string> cities = {"Pune", "Delhi", "Chennai"};
    std::vector<int> members = {420, 380, 310};

    for (auto [city, n] : std::views::zip(cities, members))
        std::cout << city << ": " << n << '\n';

    std::vector<int> v = {1, 2, 3, 4, 5, 6, 7};

    std::cout << "chunk(3):";
    for (auto group : v | std::views::chunk(3)) {
        std::cout << " [";
        for (int x : group) std::cout << x;
        std::cout << ']';                  // [123] [456] [7]
    }

    std::cout << "\nslide(3) sums:";
    for (auto window : v | std::views::slide(3)) {
        int sum = 0;
        for (int x : window) sum += x;
        std::cout << ' ' << sum;           // 6 9 12 15 18
    }
}

#include <vector>
